/* AI-assisted implementation. NASA POWER observations are loaded separately, never generated here. */
(function(){
  'use strict';
  const $=id=>document.getElementById(id);
  const variables={T2M:{title:'Annual mean air temperature',name:'Air temperature at 2 m',unit:'°C',definition:'Annual mean air temperature at 2 m, in °C. These are gridded, model-derived historical estimates.'},PRECTOTCORR:{title:'Annual average daily precipitation',name:'Corrected precipitation',unit:'mm/day',definition:'Annual average daily corrected precipitation, in mm/day. This is a rate, not an annual precipitation total.'}};
  const colors=['#176552','#b47a35'];
  let dataset=null;
  let map=null, markers=[], mapTilesReady=false;
  const locationColor=location=>colors[Math.max(0,dataset.locations.indexOf(location))%colors.length];
  const shortName=location=>location.name.replace(/^Near /,'').replace(/, Ecuador$/,'');
  function showMapFallback(){
    $('geographic-map').style.opacity='0';
    $('geographic-map').style.pointerEvents='none';
    $('map-mode').textContent='Natural Earth · Geographic reference';
  }
  function selectLocation(index){if(!dataset||!dataset.locations[index])return;$('location').value=String(dataset.locations[index].id);$('location').dispatchEvent(new Event('change',{bubbles:true}));}
  function initMap(){
    dataset.locations.forEach((location,index)=>{const coord=$(index===0?'esmeraldas-coords':'cuenca-coords');if(coord)coord.textContent=Number(location.lat).toFixed(2)+'°, '+Number(location.lon).toFixed(2)+'°';});
    showMapFallback();
    if(!window.L||map)return;
    try{
      const bounds=L.latLngBounds(dataset.locations.map(location=>[location.lat,location.lon]));
      map=L.map('geographic-map',{scrollWheelZoom:false,zoomControl:true,attributionControl:true});
      map.fitBounds(bounds,{padding:[65,48],maxZoom:7});
      const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'});
      tiles.on('tileload',()=>{mapTilesReady=true;$('geographic-map').style.opacity='1';$('geographic-map').style.pointerEvents='auto';$('map-mode').textContent='OpenStreetMap · Geographic context';});
      tiles.on('tileerror',()=>{if(!mapTilesReady)showMapFallback();});
      tiles.addTo(map);
      markers=dataset.locations.map((location,index)=>L.circleMarker([location.lat,location.lon],{radius:8,color:'#fff',weight:3,fillColor:locationColor(location),fillOpacity:1}).addTo(map).bindTooltip(shortName(location),{permanent:true,direction:'right',offset:[11,0],className:'sample-map-label'}).on('click',()=>selectLocation(index)));
      $('fit-map').addEventListener('click',()=>map.fitBounds(bounds,{padding:[65,48],maxZoom:7}));
      setTimeout(()=>{if(!mapTilesReady)showMapFallback();},8000);
    }catch(error){console.warn('Geographic tiles unavailable; reference SVG retained.',error);showMapFallback();}
  }
  function updateAssessment(selection,points,fit){
    const {key,start,end,primary}=selection;
    const v=variables[key];
    $('mean-context').textContent=shortName(primary)+' sample · '+start+'–'+end;
    $('coverage-context').textContent=start+'–'+end+' · '+points.length+' valid annual values';
    const mean=$('mean-value');mean.replaceChildren(document.createTextNode(fit?round(fit.mean):'—'));const unit=document.createElement('span');unit.textContent=v.unit;mean.append(unit);
    const title=$('assessment-title'),copy=$('assessment-copy'),confidence=$('assessment-confidence');
    if(fit){
      const direction=fit.slope>0?'upward':fit.slope<0?'downward':'flat';
      title.textContent=shortName(primary)+' · '+direction+' estimated trend';
      copy.textContent='Across '+start+'–'+end+', the selected '+(key==='T2M'?'air temperature':'daily precipitation rate')+' record changes by an estimated '+signed(fit.slope*10)+' '+v.unit+' per decade. Annual variability remains visible in the series below.';
      confidence.textContent=finite(fit.ciLow)&&finite(fit.ciHigh)?(fit.ciLow<=0&&fit.ciHigh>=0?'The nominal 95% interval includes zero. The fit allows both directions under its assumptions.':'The nominal 95% interval stays '+(fit.ciLow>0?'above':'below')+' zero under the OLS assumptions.'):'A nominal interval is unavailable for this selection.';
    }else{title.textContent='Insufficient annual observations';copy.textContent='Choose a longer time window to estimate a linear trend.';confidence.textContent='At least 10 years are required in this explorer.';}
    document.querySelectorAll('[data-location-index]').forEach(button=>{const active=String(dataset.locations[Number(button.dataset.locationIndex)]?.id)===String(primary.id);button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
    markers.forEach((marker,index)=>marker.setStyle({radius:dataset.locations[index]===primary?9:7,fillColor:locationColor(dataset.locations[index]),fillOpacity:dataset.locations[index]===primary?1:.8}));
  }
  const ns='http://www.w3.org/2000/svg';
  function svg(tag,attrs,text){const e=document.createElementNS(ns,tag);Object.entries(attrs||{}).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e;}
  function finite(v){return typeof v==='number'&&Number.isFinite(v)&&v!==-999;}
  function round(v,d=2){return Number.isFinite(v)?v.toFixed(d):'—';}
  function signed(v,d=2){return Number.isFinite(v)?(v>0?'+':'')+v.toFixed(d):'—';}
  function annualSeries(location,key,start,end){const v=location.variables[key];return v.years.map((year,i)=>({year:Number(year),value:v.values[i]})).filter(p=>p.year>=start&&p.year<=end&&finite(p.value));}
  function simpleFit(points){const n=points.length;if(n<3)return null;const xbar=points.reduce((s,p)=>s+p.year,0)/n,ybar=points.reduce((s,p)=>s+p.value,0)/n;const ss=points.reduce((s,p)=>s+(p.year-xbar)**2,0),slope=points.reduce((s,p)=>s+(p.year-xbar)*(p.value-ybar),0)/ss;return {slope,intercept:ybar-slope*xbar,mean:ybar,n};}
  function analysis(points){const fit=simpleFit(points);if(!fit)return null;const fn=window.KillaAnalysis&&window.KillaAnalysis.linearTrend;if(!fn)return {...fit,ciLow:null,ciHigh:null};let r;try{r=fn(points.map(p=>p.year),points.map(p=>p.value));}catch(e){console.error('Trend analysis failed',e);return {...fit,ciLow:null,ciHigh:null};}/* analysis.js reports its interval PER DECADE; convert to annual slope units here. */const lo=Array.isArray(r.ci95)?r.ci95[0]/10:null,hi=Array.isArray(r.ci95)?r.ci95[1]/10:null;return {...fit,raw:r,ciLow:lo,ciHigh:hi};}
  function selected(){const key=$('variable').value,start=Number($('start-year').value),end=Number($('end-year').value);const primary=dataset.locations.find(l=>String(l.id)===$('location').value)||dataset.locations[0];const locations=$('compare').checked?[primary,...dataset.locations.filter(l=>l!==primary)]:[primary];return {key,start,end,primary,locations};}
  function draw(){if(!dataset)return;let {key,start,end,primary,locations}=selected();const firstYear=dataset.period.start,lastYear=dataset.period.end;if(end-start<9){if(document.activeElement===$('start-year')){end=Math.min(lastYear,start+9);start=Math.min(start,end-9);}else{start=Math.max(firstYear,end-9);end=Math.max(end,start+9);}$('start-year').value=start;$('end-year').value=end;}const v=variables[key];$('variable-definition').textContent=v.definition;$('chart-title').textContent=v.title;const series=locations.map(l=>({location:l,points:annualSeries(l,key,start,end)}));const primaryPoints=series[0].points;const fit=analysis(primaryPoints);$('trend-label').textContent='ESTIMATED CHANGE / DECADE';$('slope-value').replaceChildren(document.createTextNode(fit?signed(fit.slope*10):'—'));const statUnit=document.createElement('span');statUnit.textContent=v.unit;$('slope-value').append(statUnit);$('mean-value').textContent=fit?`${round(fit.mean)} ${v.unit}`:'—';$('sample-count').textContent=String(primaryPoints.length);$('ci-value').textContent=fit&&finite(fit.ciLow)&&finite(fit.ciHigh)?`95% nominal interval: ${signed(fit.ciLow*10)} to ${signed(fit.ciHigh*10)} ${v.unit} / decade. Assumptions apply.`:'95% interval unavailable for this selection. A longer record or analysis module is needed.';updateAssessment({key,start,end,primary,locations},primaryPoints,fit);$('range-label').textContent=`${start}–${end}`;$('chart-caption').textContent=`Annual values · NASA POWER / MERRA-2 · ${v.unit}`;
    const legend=$('chart-legend');legend.replaceChildren();series.forEach((s,i)=>{const span=document.createElement('span'),dot=document.createElement('i');dot.className='dot';dot.style.background=locationColor(s.location);span.append(dot,document.createTextNode(s.location.name));legend.append(span);});if($('show-trend').checked){const span=document.createElement('span');span.className='legend-line';span.textContent='— — fitted trend';legend.append(span);}
    const chart=$('chart');chart.replaceChildren();chart.setAttribute('aria-label',`${v.title}, ${start} to ${end}, ${locations.map(l=>l.name).join(' compared with ')}. Real NASA POWER annual observations in ${v.unit}.`);const title=svg('title',{},`${v.title} (${v.unit})`),desc=svg('desc',{},`Historical record from ${start} through ${end}. ${primary.name}: linear trend ${fit?signed(fit.slope*10):'unavailable'} ${v.unit} per decade. Nominal confidence interval and assumptions are shown beside the chart.`);chart.append(title,desc);
    const flat=series.flatMap(s=>s.points.map(p=>p.value));if(!flat.length){chart.append(svg('text',{x:450,y:180,'text-anchor':'middle',class:'chart-empty'},'No valid observations in this selection.'));return;}let min=Math.min(...flat),max=Math.max(...flat),span=max-min||1;min-=span*.12;max+=span*.12;const pad={left:57,right:20,top:28,bottom:42},W=900,H=375,pw=W-pad.left-pad.right,ph=H-pad.top-pad.bottom;const x=year=>pad.left+(year-start)/(end-start)*pw,y=value=>pad.top+(max-value)/(max-min)*ph;for(let i=0;i<=5;i++){const val=min+(max-min)*i/5,yy=y(val);chart.append(svg('line',{x1:pad.left,x2:W-pad.right,y1:yy,y2:yy,class:'chart-grid'}));chart.append(svg('text',{x:pad.left-12,y:yy+4,'text-anchor':'end',class:'chart-axis'},round(val,key==='T2M'?1:2)));}chart.append(svg('text',{x:pad.left,y:13,class:'chart-unit'},v.unit));const ticks=[start];for(let year=Math.ceil((start+1)/5)*5;year<end;year+=5)ticks.push(year);ticks.push(end);ticks.forEach(year=>chart.append(svg('text',{x:x(year),y:H-13,'text-anchor':'middle',class:'chart-axis'},year)));series.forEach((s,i)=>{const d=s.points.map((p,j)=>`${j?'L':'M'}${x(p.year).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ');chart.append(svg('path',{d,class:'chart-series',stroke:locationColor(s.location)}));s.points.forEach(p=>{const dot=svg('circle',{cx:x(p.year),cy:y(p.value),r:3.1,class:'chart-point',fill:locationColor(s.location)});dot.append(svg('title',{},`${s.location.name} · ${p.year}: ${round(p.value)} ${v.unit}`));chart.append(dot);});const f=simpleFit(s.points);if($('show-trend').checked&&f)chart.append(svg('path',{d:`M${x(start)},${y(f.intercept+f.slope*start)}L${x(end)},${y(f.intercept+f.slope*end)}`,class:'chart-trend',stroke:locationColor(s.location)}));});
    $('record-note').textContent=`${primary.name} sample cell requested at ${primary.lat??primary.latitude}°, ${primary.lon??primary.longitude}° · ${primaryPoints.length} annual values · No simulated observations · Educational, exploratory analysis`;
  }
  function csv(){if(!dataset)return;const {key,start,end,locations}=selected();const rows=[['location','requested_latitude','requested_longitude','year','variable','value','unit','source']];locations.forEach(l=>annualSeries(l,key,start,end).forEach(p=>rows.push([l.name,l.lat??l.latitude,l.lon??l.longitude,p.year,key,p.value,variables[key].unit,'NASA POWER Monthly API / MERRA-2 annual values'])));const content=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const href=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=href;a.download=`killa-${key.toLowerCase()}-${start}-${end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);}
  async function load(){const message=$('load-message');message.hidden=false;message.removeAttribute('data-error');message.textContent='Loading the NASA observation record…';try{const response=await fetch('./data/dataset.json',{cache:'no-cache'});if(!response.ok)throw new Error(`Dataset request returned ${response.status}`);const data=await response.json();if(!Array.isArray(data.locations)||data.locations.length<2)throw new Error('The dataset must contain two sample locations.');for(const l of data.locations)for(const k of Object.keys(variables)){if(!l.variables?.[k]||!Array.isArray(l.variables[k].years)||!Array.isArray(l.variables[k].values))throw new Error('The dataset is missing a required annual record.');}dataset=data;const place=$('location');place.replaceChildren();data.locations.forEach(l=>{const option=document.createElement('option');option.value=String(l.id);option.textContent=l.name;place.append(option);});place.disabled=false;const years=data.locations[0].variables.T2M.years.map(Number);for(const id of ['start-year','end-year']){const select=$(id);select.replaceChildren();years.forEach(year=>{const option=document.createElement('option');option.value=year;option.textContent=year;select.append(option);});select.value=id==='start-year'?Math.min(...years):Math.max(...years);select.disabled=false;}$('download').disabled=false;$('lab-grid').setAttribute('aria-busy','false');message.hidden=true;$('header-record-status').textContent='Historical record loaded';initMap();draw();}catch(error){console.error(error);$('header-record-status').textContent='Historical record unavailable';message.setAttribute('data-error','true');message.textContent='The real NASA dataset is not available yet. No simulated values are displayed.';const retry=document.createElement('button');retry.textContent='Retry data';retry.addEventListener('click',load);message.append(retry);}}
  document.querySelectorAll('[data-location-index]').forEach(button=>button.addEventListener('click',()=>selectLocation(Number(button.dataset.locationIndex))));
  document.querySelectorAll('.site-header nav a').forEach(link=>link.addEventListener('click',()=>{document.querySelectorAll('.site-header nav a').forEach(item=>item.classList.toggle('nav-selected',item===link));}));
  ['variable','location','compare','start-year','end-year','show-trend'].forEach(id=>$(id).addEventListener('change',draw));$('download').addEventListener('click',csv);load();
})();
